// Import necessary classes if needed
import org.joget.apps.datalist.service.DataListService;
import org.joget.apps.app.service.AppUtil;

// Get the status value from the current row
// Assuming "status" is the column id that contains the status value
String status = (value != null) ? value.toString().toLowerCase() : null;
String displayStatus = value.toString();

// Format based on status
String formattedValue = "";

if ("Review by NC".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#27ae60;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-question-circle\" style=\"margin-right:6px;\"></i>" + displayStatus + "</font>";
} else if ("Approved by MOI".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#27ae60;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-check-circle\" style=\"margin-right:6px;\"></i>" + displayStatus + "</font>";
} else if ("Reviewed by Center Approval".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#27ae60;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-check-circle\" style=\"margin-right:6px;\"></i>" + displayStatus + "</font>";
} else if ("Public".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#27ae60;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-check-circle\" style=\"margin-right:6px;\"></i>" + displayStatus + "</font>";
} else if ("Rejected by Center Approval".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#e74c3c;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-times-circle\" style=\"margin-right:6px;\"></i> " +displayStatus+ " </font>";
}  else if ("Under Review Center".equalsIgnoreCase(status)) {
     formattedValue = "<font style=\"background-color:#27ae60;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-check-circle\" style=\"margin-right:6px;\"></i>" + displayStatus + "</font>";
} else if ("Rejected by MOI".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#e74c3c;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-times-circle\" style=\"margin-right:6px;\"></i> " +displayStatus+ " </font>";
} else if ("Rework by TC".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#e74c3c;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-times-circle\" style=\"margin-right:6px;\"></i> " +displayStatus+ " </font>";
} else if ("rejected".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#e74c3c;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-times-circle\" style=\"margin-right:6px;\"></i>Rejected</font>";
} else if ("Reject by NC".equalsIgnoreCase(status)) {
    formattedValue = "<font style=\"background-color:#e74c3c;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-times-circle\" style=\"margin-right:6px;\"></i> " +displayStatus+ " </font>";
}  else if (status == null || status.isEmpty()) {
    formattedValue = "<font style=\"background-color:#95a5a6;color:white;border-radius:6px;padding:4px 12px;font-weight:600;display:inline-flex;align-items:center;\"> <i class=\"fas fa-hourglass-half\" style=\"margin-right:6px;\"></i>Pending</font>";
} else {
    // Default formatting for any other status
    formattedValue = value.toString();
}

return formattedValue;
